mapper.select:
select from projects
and ( title like concat('%', #{keyword}, '%') or tag like concat('%', #{keyword}, '%') or status like concat('%', #{keyword}, '%') )
and ( region_adcode = #{filterRegionCode} or left(region_adcode, 4) = left(#{filterRegionCode}, 4) )
and tag = #{filterTag}
and status = #{status}
and departure_date >= #{departureDateFrom}
and departure_date <= #{departureDateTo}
and owner_account_id = #{ownerAccountId}
and leader_account_id = #{leaderAccountId}
and leader_account_id is not null
and leader_account_id is null
and status in ('OPEN', 'MATCHING') and (max_members is null or current_members is null or current_members < max_members)
order by ( case when #{sortRegionCode} is null or #{sortRegionCode} = '' then 0 when region_adcode = #{sortRegionCode} then 100 when left(region_adcode, 4) = left(#{sortRegionCode}, 4) then 50 else 0 end + case when tag is null or tag = '' then 0
when tag in
#{tag}
then 80
else 0 end ) desc, created_at desc

mapper.update:
update projects
set status = #{targetStatus}
where id = #{id}
  and status = #{expectedStatus}

update projects
set current_members = COALESCE(current_members, 0) + #{increment}
where id = #{id}
  and (max_members is null or COALESCE(current_members, 0) + #{increment} <= max_members)
